INSERT INTO changelog (title, body, created_at) VALUES
('Лабораторія: сценарії, пропозиція клієнту A4 і промпти',
'У Лабораторії два нові блоки. СЦЕНАРІЇ — покрокові варіанти рішення вкладками (суть, кроки, терміни, ціна разово/щомісяця, плюси/мінуси), «Обрати для пропозиції»; Джері складає їх сам («Джері, склади сценарії» — перенесе і те, що вже в Штурмі). ПРОПОЗИЦІЯ КЛІЄНТУ — документ A4 з 5 розділів: 1) проблема, 2) чому це проблема саме у них, 3) що ми дамо, 4) ціна і підтримка, 5) бонуси на підтримці; заголовок, підзаголовок і «від кого» (замість Client Ops). Кнопки: «Джері, склади пропозицію», «PDF A4», «.md». ПРОМПТ — кнопка «✦ Промпт» угорі сесії (пропозиція A4 / сценарії / порівняння) і біля блоків: готовий текст з усіма даними сесії, копіюєш і збираєш презентацію в Claude, Gamma чи будь-де.',
'2026-11-02 14:00:00'),
('Джері перейменовує файли на Диску',
'Новий інструмент drive_rename: Джері дає файлам у папках клієнта зрозумілі імена (напр. креативам за схемою Кут_Формат_ДД.ММ). Файли, які створила система, — одразу. Файли, які ти закинув руками, — тільки з «Повним доступом до Диску»: Налаштування → Конектори → Google → «Увімкнути» → «Перепідключити». Без нього він їх лише бачить.',
'2026-11-02 14:01:00');
